import sys


def main():
    data = sys.stdin.buffer.read().split()
    n, k = int(data[0]), int(data[1])
    a = list(map(int, data[2:2 + n]))

    def groups_needed(limit):
        count = 1
        cur = 0
        for v in a:
            if cur + v > limit:
                count += 1
                cur = v
            else:
                cur += v
        return count

    x = max(a)
    while groups_needed(x) > k:
        x += 1
    print(x)


main()
